  ["waffleAltSwitcher:previous"]="Focus previous window"
  ["wallpaperLauncher:next"]="Select the next wallpaper"
  ["wallpaperLauncher:previous"]="Select the previous wallpaper"
  ["wallpaperLauncher:applyCurrent"]="Apply the selected wallpaper and keep the launcher open"
  ["wallpaperLauncher:status"]="Return launcher mode, index, count, path, target and monitor as JSON"
  ["wallpaperSelector:toggle"]="Open/close wallpaper selector"
  ["wallpaperSelector:open"]="Open wallpaper selector"
  ["wallpaperSelector:close"]="Close wallpaper selector"
  ["wallpaperSelector:openLauncher"]="Open the compact launcher in \`static\` or \`animated\` mode"
  ["wallpaperSelector:toggleOnMonitor"]="Open wallpaper selector on a specific monitor"
  ["wallpaperSelector:random"]="Pick a random wallpaper from the current folder"
  ["wallpaperSelector:next"]="Next wallpaper as the desktop menu does it: from the current wallpaper's folder, or the shuffle's own folder; prints the file"
  ["wallpaperSelector:shuffle"]="A new wallpaper from the folder every few minutes: \`on\`, \`off\`, a number of minutes (turns it on) or \`status\`"
  ["wallpaperSelector:set"]="Apply a wallpaper (picture, GIF or video) by path, the same way the picker does"
  ["wallpaperSelector:preview"]="Show a wallpaper on the desktop without applying it: no config write, no recoloring"
  ["wallpaperSelector:cancelPreview"]="Drop the preview and go back to the applied wallpaper"
  ["wallpaperSelector:browse"]="Open the picker on a source — \`library\`, \`wallhaven\` or \`live\` (anime live wallpapers) — with a search, a folder to open (\`~/Videos\`), or \`-\` for none. Sources are an iRiS feature; other families just open the picker"
  ["wallpaperSelector:kind"]="Show only one kind of wallpaper in the library: \`all\`, \`still\`, \`live\` (videos) or \`gif\`. iRiS only; the filter also sits beside the search field whenever the folder holds more than one kind"
  ["wallpaperSelector:move"]="Move the gallery's selection by that many tiles, as the arrow keys do (negative goes back); the ring and the row glide and the desktop preview follows. iRiS only, while the picker is open"
  ["wallpaperSelector:status"]="Return picker style, open surface, target monitor and selection target as JSON"
  ["wbar:toggle"]="Show/hide taskbar"
  ["wbar:close"]="Hide taskbar"
  ["wbar:open"]="Show taskbar"
  ["widgetStacks:status"]="Returns JSON: whether stacks are live, each stack's id, pages in order, rotation, interval, the size classes all its pages share and the page shown on each output"
  ["widgetStacks:create"]="Stack two or more iRiS widgets joined with \`+\` (\`weather+monthCalendar\`); the first one's place and size become the stack's"
  ["widgetStacks:add"]="Add a widget as the last page"
  ["widgetStacks:remove"]="Take a widget out; it stays where the stack is and the layout moves it beside. A stack left with one page dissolves"
  ["widgetStacks:dissolve"]="Split the stack back into single widgets"
  ["widgetStacks:page"]="Show a page: a widget name, \`next\` or \`previous\`"
  ["widgetStacks:move"]="Move a page earlier (\`-1\`) or later (\`1\`) in the order"
  ["widgetStacks:rotate"]="\`on\` or \`off\`: the stack turns its own pages"
  ["widgetStacks:interval"]="Seconds between turns (5 to 3600)"
  ["widgetpower:status"]="Returns JSON: \`enabled\`, \`widgetsActive\`, \`pauseReason\`, and the active \`triggers\` (gameMode, fullscreen, windowsPresent, editMode)"
  ["wnotificationCenter:toggle"]="Open/close notification center"
  ["wnotificationCenter:close"]="Close notification center"
  ["wnotificationCenter:open"]="Open notification center"
  ["workspaceStrip:open"]="Keep the strip expanded"
  ["workspaceStrip:close"]="Return the strip to hover/peek mode"
  ["workspaceStrip:toggle"]="Toggle forced expansion"
  ["workspaceStrip:status"]="Return strip state (\`open\` or \`auto\`)"
  ["wwidgets:toggle"]="Open/close widgets"
  ["wwidgets:close"]="Close widgets"
  ["wwidgets:open"]="Open widgets"
  ["ytmusic:playPause"]="Toggle YtMusic play/pause"
  ["ytmusic:next"]="Play next track in YtMusic"
  ["ytmusic:previous"]="Play previous track in YtMusic"
  ["ytmusic:stop"]="Stop YtMusic playback"
  ["zoom:zoomIn"]="Increase compositor zoom"
  ["zoom:zoomOut"]="Decrease compositor zoom"
)

